#!/usr/bin/env bash
# D13 cut (c) -- scoped claim receipt for gunbc#11744.
#
# WHAT THIS COVERS: every enrolled witness module the deletion touched, plus every witness module
# that DIRECTLY imports a module the deletion touched -- 84 entries, 1232 claims. The cut
# removes authored `uses` rows whose requirement derived demand already carries, so the
# discriminating question is whether any claim over those modules changes answer; the direct
# importers are where that would show.
#
# WHY NOT THE WHOLE FLOOR: the floor is the operator's instrument. This is the scoped receipt the
# #11742 gate change asks a PR to carry, since a green CI check now executes no claims.
#
# DERIVED, NOT TRANSCRIBED: the entry set is `git diff --name-only origin/main...HEAD` joined to the
# witness importers at the head this receipt names. Re-deriving it on another head may select a
# different set.
#
# Each --entry needs its own --functions; claim_batch refuses an entry without one.
set -euo pipefail

CLAIM_BATCH="${CLAIM_BATCH:-target/release/claim_batch}"

"$CLAIM_BATCH" \
  --source-root dag \
  --source-root src/v2 \
  --hermetic \
